<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_admin();
@ini_set('display_errors','0');
$page=max(1,(int)($_GET['page']??1));$limit=20;$total=(int)db()->query("SELECT COUNT(*) FROM movies WHERE is_hidden=0")->fetchColumn();$pages=max(1,(int)ceil($total/$limit));$page=min($page,$pages);$offset=($page-1)*$limit;
$st=db()->prepare('SELECT id,thumb_url,poster_url FROM movies WHERE is_hidden=0 ORDER BY id LIMIT ? OFFSET ?');$st->bindValue(1,$limit,PDO::PARAM_INT);$st->bindValue(2,$offset,PDO::PARAM_INT);$st->execute();$rows=$st->fetchAll();$done=0;
foreach($rows as $r){foreach([['thumb','thumb_url'],['poster','poster_url']] as [$role,$col]){$v=(string)$r[$col];if(!local_media_file_valid($v))continue;$parts=preg_split('~^uploads/(posters|thumbs)/(.+)$~i',$v,-1,PREG_SPLIT_DELIM_CAPTURE);if(!$parts||count($parts)<3)continue;$path=dirname(__DIR__).'/uploads/'.$parts[1].'/'.$parts[2];if(optimize_local_image($path,$role))$done++;}}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nén ảnh FilmNova</title><style>body{font-family:system-ui;background:#0b1220;color:#eef3f8;padding:30px}.box{max-width:680px;margin:auto;background:#131d2c;border:1px solid #293750;border-radius:18px;padding:24px}.bar{height:12px;background:#0a0f18;border-radius:99px;overflow:hidden}.fill{height:100%;background:#39d98a;width:<?=round($page/$pages*100)?>%}.muted{color:#99a7ba}</style></head><body><div class="box"><h1>Nén ảnh phim</h1><p class="muted">Trang <?=$page?>/<?=$pages?> • đã tối ưu <?=$done?> file ảnh ở đợt này.</p><div class="bar"><div class="fill"></div></div><p style="margin-top:18px"><?php if($page<$pages): ?><a style="color:#7dd3fc" href="?page=<?=$page+1?>">Tiếp tục đợt kế →</a><?php else: ?><b>Hoàn tất tối ưu ảnh.</b><?php endif; ?></p></div></body></html>
